import dataclasses
import hashlib
import sys

sys.path.insert(0, "/home/x/lyra/lane-02/B/task076/tests")
sys.path.insert(0, "/home/x/lyra/lane-02/B/task076")

from thresholdsign import (
    AggregateSignature,
    HBAPB,
    HBAPBArchive,
    decode_hbapb,
    decode_hbapba,
    encode_hbapb,
    encode_hbapba,
    hbapba_message,
    verify_hbapb,
    verify_hbapba,
)
from test_audit_chain import make_key, sign_message
from test_audit_extension_proof_bundle_codec import make_other_key
from test_hbap import archive_of_size, signed_hbapb

key = make_key()
other = make_other_key()

# Build three distinct verifying HBAPB bundles.
items = (
    signed_hbapb(archive_of_size(4, key, seed_base=30100), (0, 2), key, seed=30200),
    signed_hbapb(archive_of_size(5, key, seed_base=30110), (1, 3), key, seed=30210),
    signed_hbapb(archive_of_size(7, key, seed_base=30120), (3, 6), key, seed=30220),
)
for item in items:
    assert verify_hbapb(item, key)

# Shape: frozen, positional, value equality.
sig = AggregateSignature(R=5, z=7, signer_ids=(1, 3))
a = HBAPBArchive(items, sig)
assert a.items is items and a.signature is sig
assert a == HBAPBArchive(items=items, signature=sig)
assert hash(a) == hash(HBAPBArchive(items, sig))
assert a != HBAPBArchive(items[:1], sig)
try:
    a.items = items
    raise AssertionError("not frozen")
except dataclasses.FrozenInstanceError:
    pass
HBAPBArchive("not-a-tuple", "not-a-signature")  # no construction checks

# Message layout.
def u32(v):
    return v.to_bytes(4, "big")

def varint(v):
    body = v.to_bytes((v.bit_length() + 7) // 8 or 1, "big")
    return len(body).to_bytes(4, "big") + body

framing = bytearray(u32(len(items)))
for item in items:
    enc = encode_hbapb(item)
    framing += u32(len(enc)) + enc
expected = b"ts/hbapba/m1" + hashlib.sha256(bytes(framing)).digest() + varint(key.public_key)
msg = hbapba_message(items, key.public_key)
assert msg == expected, "message layout mismatch"
assert hbapba_message(items, 0).endswith(b"\x00\x00\x00\x01\x00")
assert msg != hbapba_message(tuple(reversed(items)), key.public_key)
assert msg != hbapba_message(items[:2], key.public_key)
assert msg != hbapba_message(items, key.public_key + 1)

# Message errors.
for bad in (list(items), iter(items), items[0], "items", None, 42, b"x"):
    try:
        hbapba_message(bad, key.public_key); raise AssertionError(bad)
    except TypeError:
        pass
for bad in ("x", None, 42, b"x", object()):
    try:
        hbapba_message((bad,), key.public_key); raise AssertionError(bad)
    except TypeError:
        pass
try:
    hbapba_message((), key.public_key); raise AssertionError()
except ValueError:
    pass
for bad in ("x", None, b"x", 1.5, True, False):
    try:
        hbapba_message(items, bad); raise AssertionError(bad)
    except TypeError:
        pass
try:
    hbapba_message(items, -1); raise AssertionError()
except ValueError:
    pass

# Sign and verify.
message = hbapba_message(items, key.public_key)
outer = sign_message(key, message, signer_ids=(1, 3), seed=30300)
archive = HBAPBArchive(items, outer)
assert verify_hbapba(archive, key) is True
assert verify_hbapba(archive, other) is False

# Single item.
m1 = hbapba_message(items[:1], key.public_key)
a1 = HBAPBArchive(items[:1], sign_message(key, m1, seed=30310))
assert verify_hbapba(a1, key) is True

# Foreign nested bundle -> False.
foreign = signed_hbapb(archive_of_size(4, other, seed_base=30320), (0, 2), other, seed=30321)
mixed = (items[0], foreign)
am = HBAPBArchive(mixed, sign_message(key, hbapba_message(mixed, key.public_key), seed=30322))
assert verify_hbapba(am, key) is False

# Reorder / delete / insert / replace / tamper -> False.
reordered = tuple(reversed(items))
ar = HBAPBArchive(items, sign_message(key, hbapba_message(reordered, key.public_key), seed=30330))
assert verify_hbapba(ar, key) is False
ad = HBAPBArchive(items, sign_message(key, hbapba_message(items[:2], key.public_key), seed=30331))
assert verify_hbapba(ad, key) is False
tampered = AggregateSignature(R=outer.R, z=outer.z, signer_ids=(outer.signer_ids[-1] ^ 0xFF,))
assert verify_hbapba(HBAPBArchive(items, tampered), key) is False

# Bad bundle does not mask illegal outer signature / key.
bad_items = (foreign, items[0])
for bad_sig in (
    AggregateSignature(R=0, z=7, signer_ids=(1, 3)),
    AggregateSignature(R=5, z=-1, signer_ids=(1, 3)),
    AggregateSignature(R=5, z=7, signer_ids=()),
    AggregateSignature(R=5, z=7, signer_ids=(3, 1)),
):
    try:
        verify_hbapba(HBAPBArchive(bad_items, bad_sig), key); raise AssertionError()
    except ValueError:
        pass
for bad_key in ("x", None, 42, b"x", object()):
    try:
        verify_hbapba(archive, bad_key); raise AssertionError()
    except TypeError:
        pass
broken_key = dataclasses.replace(key, public_key=0)
try:
    verify_hbapba(archive, broken_key); raise AssertionError()
except ValueError:
    pass

# verify_hbapba type errors.
for bad in ("x", None, 42, b"x", object(), items, (items, outer)):
    try:
        verify_hbapba(bad, key); raise AssertionError(bad)
    except TypeError:
        pass
try:
    verify_hbapba(HBAPBArchive(list(items), outer), key); raise AssertionError()
except TypeError:
    pass
try:
    verify_hbapba(HBAPBArchive((), sig), key); raise AssertionError()
except ValueError:
    pass

# Codec roundtrip.
blob = encode_hbapba(archive)
assert blob.startswith(b"ts/hbapba/w1")
restored = decode_hbapba(blob)
assert restored == archive
assert encode_hbapba(restored) == blob

# Placeholder signature roundtrips too.
pa = HBAPBArchive(items, sig)
pb = encode_hbapba(pa)
assert decode_hbapba(pb) == pa

# Codec errors.
for bad in ("x", 42, None, bytearray(b"x")):
    try:
        decode_hbapba(bad); raise AssertionError(bad)
    except TypeError:
        pass
try:
    decode_hbapba(b"ts/hbapba/w2" + blob[12:]); raise AssertionError()
except ValueError:
    pass
for cut in range(12, len(blob)):
    try:
        decode_hbapba(blob[:cut]); raise AssertionError(f"cut={cut}")
    except ValueError:
        pass
try:
    decode_hbapba(blob + b"\x00"); raise AssertionError()
except ValueError:
    pass
# zero count
try:
    decode_hbapba(b"ts/hbapba/w1" + u32(0) + blob[16:]); raise AssertionError()
except ValueError:
    pass
# count mismatch
try:
    decode_hbapba(b"ts/hbapba/w1" + u32(len(items) + 1) + blob[16:]); raise AssertionError()
except ValueError:
    pass
# zero-length frame
try:
    decode_hbapba(blob[:16] + u32(0) + blob[20:]); raise AssertionError()
except ValueError:
    pass
# encode type/value errors
for bad in ("x", None, 42, b"x", object()):
    try:
        encode_hbapba(bad); raise AssertionError(bad)
    except TypeError:
        pass
try:
    encode_hbapba(HBAPBArchive((), sig)); raise AssertionError()
except ValueError:
    pass
try:
    encode_hbapba(HBAPBArchive(items, "not-a-sig")); raise AssertionError()
except TypeError:
    pass

# decode_hbapb truncation wording now uses HAMPB archive phrasing.
hblob = encode_hbapb(items[0])
wording_seen = None
for cut in range(len(b"ts/hbapb/v1"), len(hblob)):
    try:
        decode_hbapb(hblob[:cut])
    except ValueError as exc:
        text = str(exc)
        if "audit proof" in text:
            wording_seen = text
            break
assert wording_seen is None, f"residual audit proof wording: {wording_seen}"
# Confirm the new phrasing appears for a truncated bundle frame.
try:
    decode_hbapb(hblob[:-3])
except ValueError as exc:
    print("hbapb truncation message:", exc)

print("ALL SANITY CHECKS PASSED")

